#include "web.cpp"
int main(){string id;while(cin>>id){double p[35];for(double&v:p)cin>>v;Hero h;Scenario sc;Build b;int aug;Options o;auto err=configure(p,35,h,sc,b,aug,o);if(!err.empty()){cerr<<err;return 1;}int pass=0,fail=0;bool first=true;cout<<"{\"id\":\""<<id<<"\",\"items\":["<<p[1]<<','<<p[2]<<','<<p[3]<<"],\"augment\":"<<(p[30]?4:int(p[4]))<<",\"stages\":[";auto run=[&](int d){o.dps=d;Sim sim(h,sc,b,aug,o);sim.capture=false;auto r=sim.run();if(!first)cout<<',';first=false;cout<<'['<<d<<','<<r.alive<<','<<r.frame<<']';return r.alive;};for(int d=50;d<=5000;d+=50){if(!run(d)){fail=d;break;}pass=d;}if(!fail)return 2;int score=pass;for(int d=pass+1;d<fail;d++){if(!run(d))break;score=d;}cout<<"],\"coarsePass\":"<<pass<<",\"coarseFail\":"<<fail<<",\"score\":"<<score<<"}"<<endl;}}
